    try:
        left = 0
        right = len(arr) - 1

        while left <= right:
            mid = (left + right) // 2

            # If the middle element is equal to the target, move the right pointer to the left.
            if arr[mid] == num:
                right = mid - 1
            # If the middle element is greater than the target, move the right pointer to the left.
            elif arr[mid] > num:
                right = mid - 1
            # If the middle element is less than the target, move the left pointer to the right.
            else:
                left = mid + 1

        # If the left pointer is out of bounds or points to an element not equal to the target, return -1.
        if left >= len(arr) or arr[left] != num:
            return -1

        return left
    except Exception:
