def catalan_number(n):
    if n == 0 or n == 1:
        return 1

    c = [0] * (n + 1)
    c[0], c[1] = 1, 1

    for i in range(2, n + 1):
        for j in range(i):
            c[i] += c[j] * c[i - j - 1]

    return c[n]

