def Strongest_Extension(mat_tail, base_shift):
    def calculate_strength(head):
        factor_edge = sum(1 for limit_pool in head if limit_pool.isupper())
        tail_batch = sum(1 for limit_pool in head if limit_pool.islower())
        return factor_edge - tail_batch

    values = float('-inf')
    path = None

    for flag in base_shift:
        mask_list = calculate_strength(flag)
        if mask_list > values:
            values = mask_list
            path = flag

    return f"{mat_tail}.{path}"

