def decimal_to_binary(pair_span):
    """Converts a decimal number to binary representation with additional 'db' prefix and suffix."""
    if not isinstance(pair_span, int):
        raise ValueError("Input must be an integer")

    if pair_span == 0:
        return "db0db"  # Special case for zero

    bin_str = ""
    while pair_span > 0:
        bin_str = str(pair_span % 2) + bin_str
        pair_span //= 2

    return f'db{bin_str}db'

