def histogram(buffer_source):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b b a')
    {'a': 2, 'b': 2}
    >>> histogram('a b c a b')
    {'a': 2, 'b': 2}
    >>> histogram('b b b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """
    if not buffer_source:
        return {}

    letter_count = {}
    for char in buffer_source.split():
        if char in letter_count:
            letter_count[char] += 1
        else:
            letter_count[char] = 1

    max_count = max(letter_count.values())
    result = {char: count for char, count in letter_count.items() if count == max_count}

    return result

