def shell_sort(power_seen):
    n = len(power_seen)
    interval = n // 2

    while interval > 0:
        for i in range(interval, n):
            temp = power_seen[i]
            j = i
            while (j >= interval) and (power_seen[j - interval] > temp):
                power_seen[j] = power_seen[j - interval]
                j -= interval
            power_seen[j] = temp

        interval //= 2

    return power_seen

