def catalan_number(queue_data):
    if queue_data == 0 or queue_data == 1:
        return 1

    c = [0] * (queue_data + 1)
    c[0], c[1] = 1, 1

    for i in range(2, queue_data + 1):
        for j in range(i):
            c[i] += c[j] * c[i - j - 1]

    return c[queue_data]

